	.global _mo_fc_plain
	.type _mo_fc_plain, STT_FUNC
/* mo_fc_plain: fb 0, res 0, sat 0, tr 0; 43 packets a sample */
_mo_fc_plain:
	[--SP] = (R7:4);
	SP += -36;
	R3 = [SP + 68];
	I0 = R3;
	I1 = R0;
	P0 = R1;
	P2 = R2;
	R3 = 0;
	L0 = R3;
	L1 = R3;
	L2 = R3;
	L3 = R3;
	R0 = [SP + 64];
	[SP + 0] = R0;
	P1 = [SP + 72];
	R1 = [SP + 68];
	R0 = [P1 + 12];
	R0 = PACK(R1.L, R0.L);
	[SP + 4] = R0;
	P1 = [SP + 80];
	R3 = [P1];
	P1 = [SP + 76];
	R0 = [P1];
	[SP + 28] = R0;
	R4 = [P0];
	R5 = [P0 + 4];
	R6 = [P0 + 8];
	R7 = [P0 + 12];
	P1 = 64;
	LSETUP (.Lmo_fc_plain_b, .Lmo_fc_plain_e) LC0 = P1;
.Lmo_fc_plain_b:
	MNOP || R1 = [SP + 0] || R0 = [I0++];
	R0 = R0.L * R1.L;
	R0 = R0 << 2 (S);
	R0 = R0 << 2 (S);
	R0 = R0 >>> 2;
	R2 = R0.H * R0.H (IS);
	R2 = R2 >>> 12 || R1 = [P2 + 12];
	R2 = R2.L * R1.H (IS);
	R2 = R2 >>> 12;
	R2 = R0.H * R2.L;
	R0 = R0 - R2 (NS);
	R0 = R0 - R4 (S) || R1 = [P2];
	R0 = R0.H * R1.L;
	R2 = R4 + R0 (NS);
	R4 = R2 + R0 (NS);
	R0 = R2 - R5 (S);
	R0 = R0.H * R1.L;
	R2 = R5 + R0 (NS);
	R5 = R2 + R0 (NS);
	R0 = R2 - R6 (S);
	R0 = R0.H * R1.L;
	R2 = R6 + R0 (NS);
	R6 = R2 + R0 (NS);
	R0 = R2 - R7 (S);
	R0 = R0.H * R1.L;
	R2 = R7 + R0 (NS);
	R7 = R2 + R0 (NS) || [SP + 28] = R2;
	R0 = R2 - R3 (NS);
	R2 = R0 >>> 10;
	R3 = R3 + R2 (NS) || R1 = [SP + 4];
	R0 = R0.H * R1.L;
	R0 = R0 << 2 (S);
	R0 = R0 << 2 (S);
	R0 = R0 >>> 2;
	R2 = R0.H * R0.H (IS);
	R2 = R2 >>> 12 || R1 = [P2 + 12];
	R2 = R2.L * R1.H (IS);
	R2 = R2 >>> 12;
	R2 = R0.H * R2.L;
	R0 = R0 - R2 (NS) || R1 = [SP + 0];
	R0 = R0.H * R1.H;
	R0 = R0 << 3 (S);
.Lmo_fc_plain_e:
	MNOP || W[I1++] = R0.H;
	[P0] = R4;
	[P0 + 4] = R5;
	[P0 + 8] = R6;
	[P0 + 12] = R7;
	P1 = [SP + 80];
	[P1] = R3;
	P1 = [SP + 76];
	R0 = [SP + 28];
	[P1] = R0;
	SP += 36;
	(R7:4) = [SP++];
	RTS;
	.size _mo_fc_plain, .-_mo_fc_plain

